// Target-bound full-QNN Pocket runner for the frozen 0012 Android contract.
// Tokenization, state ownership, RNG, EOS orchestration and WAV encoding are CPU work;
// every neural ONNX session is fail-closed QNNExecutionProvider.
#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <memory>
#include <random>
#include <stdexcept>
#include <string>
#include <sys/resource.h>
#include <unordered_map>
#include <vector>
#include "onnxruntime_cxx_api.h"
namespace fs=std::filesystem;using Clock=std::chrono::steady_clock;
static double Now(){return std::chrono::duration<double>(Clock::now().time_since_epoch()).count();}
static long Hwm(){struct rusage r{};return getrusage(RUSAGE_SELF,&r)?-1:r.ru_maxrss;}
static uint16_t U16(std::istream&s){uint8_t b[2];s.read((char*)b,2);return b[0]|uint16_t(b[1])<<8;}
static uint32_t U32(std::istream&s){uint8_t b[4];s.read((char*)b,4);return b[0]|uint32_t(b[1])<<8|uint32_t(b[2])<<16|uint32_t(b[3])<<24;}
static std::vector<float> ReadWav(const fs::path&p){std::ifstream s(p,std::ios::binary);char h[4];s.read(h,4);if(std::string(h,4)!="RIFF")throw std::runtime_error("wav RIFF");U32(s);s.read(h,4);if(std::string(h,4)!="WAVE")throw std::runtime_error("wav WAVE");uint16_t fmt=0,ch=0,bits=0;uint32_t sr=0;std::vector<int16_t> pcm;while(s.read(h,4)){uint32_t n=U32(s);std::string id(h,4);if(id=="fmt "){fmt=U16(s);ch=U16(s);sr=U32(s);U32(s);U16(s);bits=U16(s);if(n>16)s.seekg(n-16,std::ios::cur);}else if(id=="data"){std::vector<char>b(n);s.read(b.data(),n);pcm.resize(n/2);memcpy(pcm.data(),b.data(),n);}else s.seekg(n+(n&1),std::ios::cur);}if(fmt!=1||ch!=1||sr!=24000||bits!=16||pcm.size()!=240000)throw std::runtime_error("wav contract");std::vector<float>v(pcm.size());for(size_t i=0;i<v.size();++i)v[i]=pcm[i]/32768.f;return v;}
static std::vector<float> ReadNpy(const fs::path&p){std::ifstream s(p,std::ios::binary);char m[6];s.read(m,6);if(memcmp(m,"\x93NUMPY",6))throw std::runtime_error("npy magic");uint8_t maj=s.get(),min=s.get();(void)min;uint32_t n=maj==1?U16(s):U32(s);std::string header(n,'\0');s.read(header.data(),n);if(header.find("<f4")==std::string::npos||header.find("(1, 1, 1024)")==std::string::npos)throw std::runtime_error("npy contract");std::vector<float>v(1024);s.read((char*)v.data(),v.size()*4);if(!s)throw std::runtime_error("npy short");return v;}
static void P16(std::ostream&s,uint16_t x){char b[2]={char(x),char(x>>8)};s.write(b,2);}static void P32(std::ostream&s,uint32_t x){char b[4]={char(x),char(x>>8),char(x>>16),char(x>>24)};s.write(b,4);}
static void WriteWav(const fs::path&p,const std::vector<float>&v){std::ofstream s(p,std::ios::binary|std::ios::trunc);uint32_t n=v.size()*2;s.write("RIFF",4);P32(s,36+n);s.write("WAVEfmt ",8);P32(s,16);P16(s,1);P16(s,1);P32(s,24000);P32(s,48000);P16(s,2);P16(s,16);s.write("data",4);P32(s,n);for(float x:v){long q=std::lround(std::clamp(x,-1.f,1.f)*32767.f);P16(s,uint16_t(int16_t(std::clamp(q,-32768L,32767L))));}if(!s)throw std::runtime_error("wav write");}
struct MS{std::string name,prefix;std::unique_ptr<Ort::Session>s;std::vector<std::string>in,out;std::vector<const char*>ip,op;double create=0;};
static Ort::SessionOptions Opt(const std::string&backend,const std::string&prefix,bool prof){Ort::SessionOptions o;o.SetIntraOpNumThreads(1);o.SetInterOpNumThreads(1);o.SetExecutionMode(ExecutionMode::ORT_SEQUENTIAL);o.SetGraphOptimizationLevel(GraphOptimizationLevel::ORT_ENABLE_BASIC);if(prof)o.EnableProfiling(prefix.c_str());if(backend!="cpu"){o.AddConfigEntry("session.disable_cpu_ep_fallback","1");std::unordered_map<std::string,std::string>q={{"backend_path",backend},{"offload_graph_io_quantization","0"},{"htp_performance_mode","burst"},{"soc_model","43"}};if(prof){q["profiling_level"]="detailed";q["profiling_file_path"]=prefix+".qnn.csv";}o.AppendExecutionProvider("QNN",q);}return o;}
static MS Load(Ort::Env&e,const fs::path&p,const std::string&name,const fs::path&pd,const std::string&backend,bool prof){MS m;m.name=name;m.prefix=(pd/name).string();auto o=Opt(backend,m.prefix,prof);double t=Now();m.s=std::make_unique<Ort::Session>(e,p.c_str(),o);m.create=Now()-t;Ort::AllocatorWithDefaultOptions a;for(size_t i=0;i<m.s->GetInputCount();++i){auto x=m.s->GetInputNameAllocated(i,a);m.in.emplace_back(x.get());}for(size_t i=0;i<m.s->GetOutputCount();++i){auto x=m.s->GetOutputNameAllocated(i,a);m.out.emplace_back(x.get());}for(auto&x:m.in)m.ip.push_back(x.c_str());for(auto&x:m.out)m.op.push_back(x.c_str());return m;}
static std::vector<Ort::Value> Run(MS&m,std::vector<Ort::Value>&v){if(v.size()!=m.ip.size())throw std::runtime_error(m.name+" input count");return m.s->Run(Ort::RunOptions{nullptr},m.ip.data(),v.data(),v.size(),m.op.data(),m.op.size());}
template<class T>static Ort::Value TV(Ort::MemoryInfo&mi,std::vector<T>&v,std::initializer_list<int64_t>sh){std::vector<int64_t>s(sh);return Ort::Value::CreateTensor<T>(mi,v.data(),v.size(),s.data(),s.size());}
static std::vector<Ort::Value> InitFlow(Ort::AllocatorWithDefaultOptions&a){std::vector<Ort::Value>x;std::array<int64_t,4>c{1,16,256,64};for(int i=0;i<12;++i){auto v=Ort::Value::CreateTensor<float>(a,c.data(),c.size());std::fill(v.GetTensorMutableData<float>(),v.GetTensorMutableData<float>()+16*256*64,0);x.push_back(std::move(v));}std::array<int64_t,4>ms{1,1,1,256};auto m=Ort::Value::CreateTensor<float>(a,ms.data(),ms.size());std::fill(m.GetTensorMutableData<float>(),m.GetTensorMutableData<float>()+256,-10000);x.push_back(std::move(m));return x;}
static std::vector<Ort::Value> FlowCall(MS&m,Ort::Value*lead,std::vector<int64_t>&pos,std::vector<Ort::Value>&st,Ort::MemoryInfo&mi){std::vector<Ort::Value>v;if(lead)v.push_back(std::move(*lead));v.push_back(TV(mi,pos,{(int64_t)pos.size()}));v.push_back(std::move(st[12]));for(int i=0;i<12;++i)v.push_back(std::move(st[i]));auto r=Run(m,v);size_t off=m.name.find("prefill")!=std::string::npos?0:2;st.clear();for(size_t i=0;i<13;++i)st.push_back(std::move(r[off+i]));return r;}
static std::vector<Ort::Value> InitDecoder(MS&m,Ort::AllocatorWithDefaultOptions&a){std::vector<Ort::Value>x;for(size_t i=1;i<m.in.size();++i){auto ti=m.s->GetInputTypeInfo(i).GetTensorTypeAndShapeInfo();auto sh=ti.GetShape();auto ty=ti.GetElementType();auto v=Ort::Value::CreateTensor(a,sh.data(),sh.size(),ty);size_t n=ti.GetElementCount(),bytes=ty==ONNX_TENSOR_ELEMENT_DATA_TYPE_FLOAT?n*4:ty==ONNX_TENSOR_ELEMENT_DATA_TYPE_INT64?n*8:n;memset(v.GetTensorMutableRawData(),ty==ONNX_TENSOR_ELEMENT_DATA_TYPE_BOOL?1:0,bytes);x.push_back(std::move(v));}if(x.size()!=56)throw std::runtime_error("decoder state ABI");return x;}
static std::vector<float> CopyFloat(Ort::Value&v){auto i=v.GetTensorTypeAndShapeInfo();auto*p=v.GetTensorData<float>();return {p,p+i.GetElementCount()};}
int main(int ac,char**av){try{if(ac!=8)throw std::runtime_error("usage: runner MODEL_DIR WAV PROFILE_DIR|- BACKEND TEMPERATURE MAX_FRAMES VARIANT");fs::path root=av[1],wav=av[2],pd=av[3];std::string backend=av[4],variant=av[7];float temp=std::stof(av[5]);int maxf=std::stoi(av[6]);bool prof=pd!="-";if(prof)fs::create_directories(pd);if(temp<=0||maxf<1||maxf>100)throw std::runtime_error("range");Ort::Env env(ORT_LOGGING_LEVEL_WARNING,"pocket-full-qnn");double load0=Now();std::vector<MS>ms;auto L=[&](const char*f,const char*n)->MS&{std::cerr<<"loading "<<n<<" hwm_kb="<<Hwm()<<"\n"<<std::flush;ms.push_back(Load(env,root/f,n,pd,backend,prof));std::cerr<<"loaded "<<n<<" seconds="<<ms.back().create<<" hwm_kb="<<Hwm()<<"\n"<<std::flush;return ms.back();};ms.reserve(10);MS&tc=L("text_conditioner.onnx","text");MS&enc=L("mimi_encoder.onnx","encoder");MS&pv=L("flow_prefill_voice126.onnx","prefill_voice");MS&pt=L("flow_prefill_text26.onnx","prefill_text");MS&ab=L("flow_ar_bos1.onnx","ar_bos");MS&al=L("flow_ar_latent1.onnx","ar_latent");MS&fl=L("flow.onnx","flow");MS&d12=L("mimi_decoder12.onnx","decoder12");MS&d6=L("mimi_decoder6.onnx","decoder6");MS&d1=L("mimi_decoder1.onnx","decoder1");double load=Now()-load0;Ort::MemoryInfo mi=Ort::MemoryInfo::CreateCpu(OrtArenaAllocator,OrtMemTypeDefault);Ort::AllocatorWithDefaultOptions alloc;double t0=Now(),te=0,tt=0,tp=0,ta=0,tf=0,td=0;
 auto audio=ReadWav(root/"bria.wav");std::vector<Ort::Value>ei;ei.push_back(TV(mi,audio,{1,1,240000}));double t=Now();auto er=Run(enc,ei);te+=Now()-t;auto ev=CopyFloat(er[0]);auto bos=ReadNpy(root/"bos_before_voice.npy");std::vector<float>voice;voice.reserve(126*1024);voice.insert(voice.end(),bos.begin(),bos.end());voice.insert(voice.end(),ev.begin(),ev.end());if(voice.size()!=126*1024)throw std::runtime_error("voice shape");
 std::vector<int64_t>ids={1456,603,597,602,854,640,791,261,260,1332,323,288,285,287,489,594,1355,1049,265,311,2081,3697,273,519,1836,263};std::vector<Ort::Value>ti;ti.push_back(TV(mi,ids,{1,26}));t=Now();auto tr=Run(tc,ti);tt+=Now()-t;auto text=CopyFloat(tr[0]);
 auto state=InitFlow(alloc);std::vector<int64_t>pos(126);for(int i=0;i<126;++i)pos[i]=i;auto vv=TV(mi,voice,{1,126,1024});t=Now();FlowCall(pv,&vv,pos,state,mi);tp+=Now()-t;pos.resize(26);for(int i=0;i<26;++i)pos[i]=126+i;auto tv=TV(mi,text,{1,26,1024});t=Now();FlowCall(pt,&tv,pos,state,mi);tp+=Now()-t;
 std::mt19937 rng(0);std::vector<float>cur(32),latents,logits;int eos=-1;std::vector<float>zero{0},one{1};for(int step=0;step<maxf;++step){pos={152+step};t=Now();std::vector<Ort::Value>r;if(step==0)r=FlowCall(ab,nullptr,pos,state,mi);else{auto cv=TV(mi,cur,{1,1,32});r=FlowCall(al,&cv,pos,state,mi);}ta+=Now()-t;float logit=*r[1].GetTensorData<float>();logits.push_back(logit);if(eos<0&&logit>-4)eos=step;if(eos>0&&step>=eos+3)break;std::normal_distribution<float>dist(0,std::sqrt(temp));std::vector<float>noise(32);for(float&x:noise)x=dist(rng);std::vector<Ort::Value>fi;fi.push_back(std::move(r[0]));fi.push_back(TV(mi,zero,{1,1}));fi.push_back(TV(mi,one,{1,1}));fi.push_back(TV(mi,noise,{1,32}));t=Now();auto fr=Run(fl,fi);tf+=Now()-t;auto dir=fr[0].GetTensorData<float>();for(int i=0;i<32;++i)cur[i]=noise[i]+dir[i];latents.insert(latents.end(),cur.begin(),cur.end());}int frames=latents.size()/32;if(!frames)throw std::runtime_error("no latents");
 auto ds=InitDecoder(d12,alloc);std::vector<float>out;int full=frames/12,rem=frames%12;auto DC=[&](MS&m,int start,int n){std::vector<float>x(latents.begin()+start*32,latents.begin()+(start+n)*32);std::vector<Ort::Value>di;di.push_back(TV(mi,x,{1,n,32}));for(auto&z:ds)di.push_back(std::move(z));double q=Now();auto dr=Run(m,di);td+=Now()-q;auto y=CopyFloat(dr[0]);out.insert(out.end(),y.begin(),y.end());ds.clear();for(int i=0;i<56;++i)ds.push_back(std::move(dr[1+i]));};for(int i=0;i<full;++i)DC(d12,i*12,12);if(rem==6)DC(d6,full*12,6);else for(int i=0;i<rem;++i)DC(d1,full*12+i,1);if((int)out.size()!=frames*1920)throw std::runtime_error("audio length");WriteWav(wav,out);double total=Now()-t0;std::vector<std::string>profiles;if(prof)for(auto&m:ms){auto p=m.s->EndProfilingAllocated(alloc);profiles.emplace_back(p.get());}
 std::cout<<"{\"route\":\""<<(backend=="cpu"?"cpu_derivative_oracle":"full_qnn_candidate")<<"\",\"variant\":\""<<variant<<"\",\"provider\":\""<<(backend=="cpu"?"CPUExecutionProvider":"QNNExecutionProvider")<<"\",\"cpu_fallback\":"<<(backend=="cpu"?"null":"false")<<",\"graph_optimization\":\"basic\",\"temperature\":"<<temp<<",\"seed\":0,\"max_frames\":"<<maxf<<",\"load_seconds\":"<<load<<",\"generation_seconds\":"<<total<<",\"component_seconds\":{\"encoder\":"<<te<<",\"text\":"<<tt<<",\"prefill\":"<<tp<<",\"ar\":"<<ta<<",\"flow\":"<<tf<<",\"decoder\":"<<td<<"},\"eos_step\":"<<eos<<",\"eos_logits\":[";for(size_t i=0;i<logits.size();++i){if(i)std::cout<<",";std::cout<<logits[i];}std::cout<<"],\"latent_frames\":"<<frames<<",\"samples\":"<<out.size()<<",\"audio_seconds\":"<<out.size()/24000.0<<",\"rtf\":"<<total/(out.size()/24000.0)<<",\"vm_hwm_kb\":"<<Hwm()<<",\"ort_profiles\":[";for(size_t i=0;i<profiles.size();++i){if(i)std::cout<<",";std::cout<<"\""<<profiles[i]<<"\"";}std::cout<<"]}\n";return 0;}catch(const Ort::Exception&e){std::cerr<<"ORT "<<e.GetOrtErrorCode()<<": "<<e.what()<<"\n";return 2;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<"\n";return 3;}}
